  /** Open in Footage Panel. Opens the footage item `item` (id or name) in the Footage panel, at its first frame. Params: {item: id|name}. Changes the document. */
  "footage.open": { /** id|name */ item?: number }
  /** Footage Panel State. Returns the Footage panel state: the open item, its name, the panel time (seconds, frame, timecode), the In and Out points, duration and frame rate; null when no footage is open. Params: {}. */
  "footage.info": Record<string, never>
