  /** Set In Point. Sets the Footage panel's In point for the open footage at `time` (source seconds) or `frame`, default the panel time; the range overlay and insert edits use. Params: {time? | frame? (default: the panel's time)}. Changes the document. */
  "footage.setIn": { /** default: the panel's time; one of several alternative parameters */ frame?: number; /** default: the panel's time; one of several alternative parameters */ time?: number }
  /** Set Out Point. Sets the Footage panel's Out point for the open footage at `time` (source seconds) or `frame`, default the panel time; the range overlay and insert edits use. Params: {time? | frame? (default: the panel's time)}. Changes the document. */
