  "footage.overlayEdit": { /** comp s; default the current time */ at?: number; comp?: number; /** (s) */ in?: number; item?: number; /** read by the command beside its listed parameters */ layer?: number; /** (s) */ out?: number; /** read by the command beside its listed parameters */ tracker?: Json }
  /** Ripple Insert Edit. Inserts footage `item`'s In?Out range (or `in`/`out` seconds) into `comp` at `at` (default now) and splits and pushes every later layer later by its length. Use footage.overlayEdit to overlap instead. Params: {item?, comp?, in? (s), out? (s), at? (comp s; default the current time)}. Changes the document. */
  "footage.rippleInsertEdit": { /** comp s; default the current time */ at?: number; comp?: number; /** (s) */ in?: number; item?: number; /** read by the command beside its listed parameters */ layer?: number; /** (s) */ out?: number; /** read by the command beside its listed parameters */ tracker?: Json }
  /** Auto-trace. Traces the edges of `layer` (its `channel`: alpha, red, green, blue or luminance) into masks, at the current frame or over the work area (`timeSpan`): `threshold`, `blur`, `tolerance`, `minimumArea`, `cornerRoundness`, `invert`; `applyToNewLayer` puts the masks on a new solid. Params: {layer?, timeSpan?: currentFrame|workArea, channel?: alpha|red|green|blue|luminance, invert?, blur? (px, 1), tolerance? (px, 1), threshold? (%, 50), minimumArea? (px, 10), cornerRoundness? (%, 50), applyToNewLayer?}. Changes the document. */
  "layer.autoTrace": { applyToNewLayer?: boolean; /** px, 1 */ blur?: number; channel?: "alpha" | "red" | "green" | "blue" | "luminance"; /** %, 50 */ cornerRoundness?: number; invert?: boolean; layer?: number; /** px, 10 */ minimumArea?: number; /** %, 50 */ threshold?: number; timeSpan?: "currentFrame" | "workArea"; /** px, 1 */ tolerance?: number }
