  "layer.alignVideoToData": { /** read by the command beside its listed parameters */ comp?: number; /** data footage id|name */ data?: string; /** comp s of the first sample, 0 */ dataStart?: number; /** time field */ key?: string; layer?: number; /** ISO date-time | hh:mm:ss | timecode | seconds (default: file creation time); default: file creation time */ videoStart?: string }
  /** Nudge Layers. The arrow keys in the Composition panel: move the selected (unlocked) layers by `x`, `y` comp pixels; After Effects nudges 1 pixel at the panel's magnification, 10 with Shift. Each call is one undo step. Params: {x?, y? (comp pixels), layers?, merge?}. Changes the document. */
  "layer.nudge": { /** read by the command beside its listed parameters */ comp?: number; /** read by the command beside its listed parameters */ layer?: number; layers?: Array<number>; merge?: string; x?: number; /** comp pixels */ y?: number }
