  "layer.align": { /** read by the command beside its listed parameters */ comp?: number; edge?: "left" | "hcenter" | "right" | "top" | "vcenter" | "bottom"; /** read by the command beside its listed parameters */ layer?: number; layers?: Array<number>; /** default composition */ to?: "composition" | "selection" }
