  "layer.distribute": { /** read by the command beside its listed parameters */ comp?: number; /** read by the command beside its listed parameters */ edge?: string; /** read by the command beside its listed parameters */ layer?: number; layers?: Array<number>; /** edges or centres */ mode?: "left" | "hcenter" | "right" | "top" | "vcenter" | "bottom" }
