  "contentFill.generate": { /** (px) */ alphaExpansion?: number; layer?: number; lightingCorrection?: "none" | "subtle" | "moderate" | "strong"; /** object|surface|edgeBlend */ method?: string; outputDir?: string; range?: "workArea" | "entire"; referenceLayer?: string; /** s */ referenceTime?: number; wait?: boolean }
  /** Content-Aware Fill Layer. Content-Aware Fill: renders a fill layer that removes the masked area of `layer` over the work area or the whole comp, with the options of contentFill.set (or given here); writes the frames to `outputDir`. Params: {layer?, method?: object|surface|edgeBlend, range?: workArea|entire, alphaExpansion? (px), lightingCorrection?: none|subtle|moderate|strong, referenceLayer?, referenceTime? (s), outputDir?, wait?: bool}. Changes the document. */
  "layer.newContentAwareFill": { /** (px) */ alphaExpansion?: number; /** read by the command beside its listed parameters */ comp?: number; layer?: number; lightingCorrection?: "none" | "subtle" | "moderate" | "strong"; /** object|surface|edgeBlend */ method?: string; outputDir?: string; range?: "workArea" | "entire"; referenceLayer?: string; /** s */ referenceTime?: number; wait?: boolean }
  /** Browser Storage. Returns the browser storage the web app uses: availability, backend, usage and quota, whether storage is persistent, stored files by kind and the disk cache statistics. {available: false} on desktop. Params: {} ? {available, backend, usage, quota, persisted, files: {count, bytes, media, projects, autoSaves}, diskCache: {enabled, entries, bytes, maxBytes, hits, misses, writes, evictions}}. */
  "storage.info": Record<string, never>
  /** Request Persistent Storage. Asks the browser to make the web app's storage persistent so it isn't evicted. Returns {requested, persisted}. Params: {} ? {requested, persisted}. Changes the document. */
  "storage.persist": Record<string, never>
  /** Clear Browser Storage. Delete stored data: `diskCache` (cached frames), `media` (imported footage), `projects` (saved projects), `autoSaves`, or `all` of them (settings stay). Returns what was removed: `{cleared, entries, bytes}`. Params: {what: diskCache|media|projects|autoSaves|all} ? {cleared, entries, bytes}. Changes the document. */
